import React from "react";
import { NavLink, useNavigate } from "react-router-dom";
import Brand from "../ui/Brand";

const links = [
  { to: "/dashboard", label: "Overview", icon: "▦" },
  { to: "/reports", label: "Reports queue", icon: "▤", badge: "12" },
  { to: "/analytics", label: "Analytics", icon: "◷" },
  { to: "/officers", label: "Officers", icon: "♙" },
];

const Sidebar = ({ open, desktopOpen, onClose }) => {
  const navigate = useNavigate();

  return (
    <aside
      className={`fixed inset-y-0 left-0 z-30 flex w-[248px] flex-col border-r border-[#e7ebe8] bg-white px-4 py-6 transition-transform duration-200 ${
        open ? "translate-x-0 shadow-2xl" : "-translate-x-full"
      } ${
        desktopOpen ? "lg:translate-x-0" : "lg:-translate-x-full"
      }`}
    >
      <div className="relative mb-7 px-1.5">
        <Brand />
        <button
          aria-label="Close menu"
          className="absolute right-0 top-0 text-2xl text-gray-500 lg:hidden"
          onClick={onClose}
        >
          ×
        </button>
      </div>

      <div className="mb-7 flex items-center gap-2.5 rounded-lg border border-gray-100 bg-gray-50 p-2.5">
        <span className="grid h-8 w-8 place-items-center rounded-lg bg-[#dcebe3] font-bold text-[#185835]">
          N
        </span>
        <span>
          <b className="block text-xs">NEMA Malawi</b>
          <small className="mt-0.5 block text-[10px] text-gray-500">
            Regional operations
          </small>
        </span>
        <span className="ml-auto text-gray-500">⌄</span>
      </div>

      <p className="mb-2 px-2.5 text-[9px] font-bold tracking-widest text-gray-400">
        WORKSPACE
      </p>
      <nav className="space-y-1">
        {links.map((link) => (
          <NavLink
            key={link.to}
            to={link.to}
            onClick={onClose}
            className={({ isActive }) =>
              `flex items-center gap-3 rounded-lg px-3 py-2.5 text-xs transition ${
                isActive
                  ? "bg-[#eaf2ed] font-bold text-[#185835]"
                  : "text-gray-600 hover:bg-gray-50"
              }`
            }
          >
            <span className="w-[18px] text-center text-base">{link.icon}</span>
            {link.label}
            {link.badge && (
              <span className="ml-auto rounded-full bg-[#f3e8dc] px-2 py-0.5 text-[10px] font-bold text-[#a25a20]">
                {link.badge}
              </span>
            )}
          </NavLink>
        ))}
      </nav>

      <div className="mt-auto">
        <div className="mb-4 rounded-xl bg-[#f3f7f4] p-3">
          <span className="text-base text-[#185835]">✳</span>
          <b className="mt-2 block text-[11px]">Need a hand?</b>
          <p className="my-1.5 text-[10px] leading-relaxed text-gray-500">
            Visit the operations guide for help with your dashboard.
          </p>
          <button
            className="text-[10px] font-bold text-[#185835]"
            onClick={() => window.alert("Operations guide coming soon")}
          >
            Open guide <span className="ml-1">↗</span>
          </button>
        </div>
        <button
          className="flex w-full items-center gap-2.5 border-t border-gray-100 pt-3 text-left"
          onClick={() => navigate("/login")}
        >
          <span className="grid h-8 w-8 place-items-center rounded-full bg-[#e5e8d9] text-[10px] font-bold text-[#526c46]">
            TK
          </span>
          <span>
            <b className="block text-xs">Thoko Kalua</b>
            <small className="mt-0.5 block text-[10px] text-gray-500">
              Administrator
            </small>
          </span>
          <span className="ml-auto text-lg text-gray-500">···</span>
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;
